-- =====================================================================
-- Solar One Energy: site content from the company profile PDF (2026-10-17)
--
-- Loads the hero, packages, contact and projects sections into
-- public.site_content, so the public site and the admin panel read them from
-- Supabase. Leaves the calculator (roi) row as it is.
--
-- Run once: Supabase Dashboard -> SQL Editor -> New query -> paste all -> Run.
-- Safe to re-run; it overwrites these four sections with the values below,
-- including any edits made in the admin panel since.
-- =====================================================================

-- 1. Allow the new "projects" section (portfolio + about-us figures)
do $$
declare r record;
begin
  for r in select conname from pg_constraint
           where conrelid = 'public.site_content'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) like '%''hero''%'
  loop
    execute format('alter table public.site_content drop constraint %I', r.conname);
  end loop;
end $$;

alter table public.site_content
  add constraint site_content_key_check
  check (key in ('hero', 'packages', 'roi', 'contact', 'projects', 'testimonials'));

